import crypto from "node:crypto";

export const getObjectHash = (obj: Record<string, any>) => {
  const hash = crypto.createHash("md5");
  const v = Object.values(obj).join(";");
  hash.update(v);
  return hash.digest("base64");
};

interface IAuthHeader {
  data: string;
  gameId: string;
  version: string;
  salt: string;
}
export const getAuthHeader = function (options: IAuthHeader) {
  const head = {
    game_tag: options.gameId,
    time: Math.floor(Date.now() / 1000),
    version: options.version,
  };
  const signStr = `${JSON.stringify(head)}${options.data || ""}${options.salt}`;
  const sign = crypto.createHash("md5").update(signStr).digest("hex");

  return JSON.stringify({
    head,
    sign,
  });
};
